package niimblue

import (
	"bytes"
	_ "embed"
	"encoding/hex"
	"regexp"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
)

// B1 connect handshake + print job responses, generated by test/gen_print_dump.ts.
//
//go:embed testdata/b1_print_dump.txt
var b1Dump string

var notSupported = []byte{0x55, 0x55, 0x00, 0x01, 0x01, 0x00, 0xaa, 0xaa}

type dumpEntry struct {
	req    []byte
	prefix bool
	resp   []byte // nil = no response
}

// fakePrinter answers requests from a niimbluelib style hex dump, like
// NiimbotVirtualClient does on the JS side, but over a real transport.
//
// Print status is stateful so multi page jobs finish: PrintStart resets the
// page counter, SetPageSize remembers the copies of the page, PageEnd adds
// them and PrintStatus reports the count.
//
// What a print looks like on paper is tested with the library's PNG printer
// (ConnectPNG); this fake checks the bytes on the transport.
type fakePrinter struct {
	entries []dumpEntry

	mu       sync.Mutex
	requests [][]byte
	copies   int
	printed  int

	// hold: report no printed pages yet, so the job stays "printing"
	hold atomic.Bool
}

// Command ids (niimbluelib RequestCommandId)
const (
	cmdPrintStart  = 0x01
	cmdSetPageSize = 0x13
	cmdPageEnd     = 0xe3
	cmdPrintStatus = 0xa3
	cmdPrintEnd    = 0xf3
)

// frameCmd returns command and data of a request frame.
func frameCmd(fr []byte) (byte, []byte) {
	i := bytes.Index(fr, []byte{0x55, 0x55})
	if i < 0 || len(fr) < i+4 {
		return 0, nil
	}
	n := int(fr[i+3])
	if len(fr) < i+4+n {
		return fr[i+2], nil
	}
	return fr[i+2], fr[i+4 : i+4+n]
}

// statusPacket builds the PrintStatus response for `page` printed pages.
func statusPacket(page int) []byte {
	data := []byte{byte(page >> 8), byte(page), 0x64, 0x64}
	chk := byte(0xb3) ^ byte(len(data))
	for _, b := range data {
		chk ^= b
	}
	return append(append([]byte{0x55, 0x55, 0xb3, byte(len(data))}, data...), chk, 0xaa, 0xaa)
}

// commands returns the command ids of all requests so far.
func (fp *fakePrinter) commands() []byte {
	fp.mu.Lock()
	defer fp.mu.Unlock()
	cmds := make([]byte, 0, len(fp.requests))
	for _, r := range fp.requests {
		c, _ := frameCmd(r)
		cmds = append(cmds, c)
	}
	return cmds
}

// framesOf returns the data of all requests with the given command.
func (fp *fakePrinter) framesOf(cmd byte) [][]byte {
	fp.mu.Lock()
	defer fp.mu.Unlock()
	var out [][]byte
	for _, r := range fp.requests {
		if c, d := frameCmd(r); c == cmd {
			out = append(out, d)
		}
	}
	return out
}

var commentRe = regexp.MustCompile(`\(.*?\)`)

func newFakePrinter(t testing.TB, dump string) *fakePrinter {
	t.Helper()
	fp := &fakePrinter{}
	var cur *dumpEntry
	for _, line := range strings.Split(dump, "\n") {
		line = strings.TrimSpace(line)
		if len(line) < 3 {
			continue
		}
		dir, val := line[:2], commentRe.ReplaceAllString(line[2:], "")
		val = strings.ReplaceAll(val, " ", "")
		switch dir {
		case ">>":
			e := dumpEntry{prefix: strings.HasSuffix(val, "*")}
			b, err := hex.DecodeString(strings.TrimSuffix(val, "*"))
			if err != nil {
				t.Fatalf("bad dump line %q: %v", line, err)
			}
			e.req = b
			fp.entries = append(fp.entries, e)
			cur = &fp.entries[len(fp.entries)-1]
		case "<<":
			if cur == nil {
				t.Fatalf("response without request: %q", line)
			}
			if !strings.EqualFold(val, "NA") {
				b, err := hex.DecodeString(val)
				if err != nil {
					t.Fatalf("bad dump line %q: %v", line, err)
				}
				cur.resp = b
			}
			cur = nil
		}
	}
	return fp
}

// respond returns the response to a single request frame (nil = none).
func (fp *fakePrinter) respond(req []byte) []byte {
	cmd, data := frameCmd(req)
	fp.mu.Lock()
	fp.requests = append(fp.requests, append([]byte(nil), req...))
	switch cmd {
	case cmdPrintStart:
		fp.printed, fp.copies = 0, 1
	case cmdSetPageSize:
		fp.copies = 1
		if len(data) >= 6 {
			fp.copies = int(data[4])<<8 | int(data[5])
		}
	case cmdPageEnd:
		fp.printed += fp.copies
	case cmdPrintStatus:
		page := fp.printed
		fp.mu.Unlock()
		if fp.hold.Load() {
			page = 0
		}
		return statusPacket(page)
	}
	fp.mu.Unlock()
	for _, e := range fp.entries {
		if (e.prefix && bytes.HasPrefix(req, e.req)) || (!e.prefix && bytes.Equal(req, e.req)) {
			return e.resp
		}
	}
	return notSupported
}

func (fp *fakePrinter) requestCount() int {
	fp.mu.Lock()
	defer fp.mu.Unlock()
	return len(fp.requests)
}

// splitFrames extracts complete packets ([03] 55 55 cmd len data.. crc aa aa)
// from a byte stream, returning the frames and the unconsumed rest.
func splitFrames(buf []byte) (frames [][]byte, rest []byte) {
	for {
		start := bytes.Index(buf, []byte{0x55, 0x55})
		if start < 0 || len(buf) < start+4 {
			return frames, buf
		}
		total := 2 + 1 + 1 + int(buf[start+3]) + 1 + 2
		if len(buf) < start+total {
			return frames, buf
		}
		from := start
		if start > 0 && buf[start-1] == 0x03 { // connect packet prefix
			from = start - 1
		}
		frames = append(frames, buf[from:start+total])
		buf = buf[start+total:]
	}
}
